/* ================= 0.37: фильмы авиаторов Германии, Британии, Италии и России — Фоккер, Юнкерс, Сопвич, де Хэвилленд, Капрони, Сикорский =================
   После Версаля глава Фоккера и Юнкерса знает, перенесли ли вы сборку за границу; у Сикорского после революции — уехали вы
   (в Америку или в другую страну) или остались «красным директором». */
SAGA.fokker=[
  {id:'fo1',t:'Летучий голландец',y:1912,when:'start',
   sc:[{img:'Fokker Spin',say:'Антони Фоккер родился на Яве, в семье голландского плантатора, и учился плохо. Зато в двадцать лет построил аэроплан «Паук» — и сам научился на нём летать.'},
       {img:'Anthony Fokker',say:'В день рождения королевы, в августе 1911 года, Фоккер облетел собор Святого Бавона в родном Харлеме. Город ликовал. А строить аэропланы он едет в Германию: под Берлином, на поле Йоханнисталь, есть всё — моторы, механики и покупатели.'},
       {who:'Механик',line:'Минхер Фоккер, у нас три аэроплана, пятеро механиков и ни одного заказа. Зато вы летаете лучше всех в Йоханнистале.'}],
   q:'С чего начать?',
   o:[{t:'Лётная школа на поле',fx:{cash:500,b:{airPriv:[1.08,24]}},res:'Ученики платят за уроки, а Фоккер учит их на своих «Пауках». Каждый выпускник — будущий покупатель.'},
      {t:'Предложить «Паука» армиям',fx:{cash:-300,b:{airMil:[1.08,36]}},res:'Голландское правительство отказывает. Покупают только немцы. Это решит всю жизнь Фоккера.'},
      {t:'Показательные полёты — трюки над толпой',fx:{afame:4,b:{airFame:[1.15,24]}},res:'Фоккер крутит виражи над головами зрителей и сажает «Паука» у самой трибуны. Газеты зовут его летучим голландцем.'}]},
  {id:'fo2',t:'Синхронизатор',y:1915,when:'t:1915.45',
   sc:[{img:'Roland Garros (aviator)',say:'Апрель 1915 года. Француз Ролан Гаррос стреляет из пулемёта прямо через винт: стальные клинья на лопастях отбивают пули, которые в них попадают. За две недели он сбивает троих немцев.'},
       {img:'Morane-Saulnier L',say:'Восемнадцатого апреля мотор Гарроса глохнет над германскими окопами. Аэроплан почти цел. Его везут в Берлин — и зовут Фоккера: сделайте так же, только лучше.'},
       {img:'Fokker E.I',say:'Инженеры Фоккера делают механизм, который сам останавливает пулемёт, когда перед стволом проходит лопасть. Фоккер ставит его на свой моноплан и сам показывает генералам, как стреляет сквозь винт.'},
       {who:'Генерал',line:'Вы покажете это в бою, господин Фоккер? Нет? Вы подданный нейтральной Голландии… Хорошо. Найдём лётчиков.'}],
   q:'Кому доверить новую машину?',
   o:[{t:'Бёльке и Иммельману — лучшим',fx:{afame:4,b:{airFight:[1.1,36]}},res:'Освальд Бёльке и Макс Иммельман начинают сбивать союзников одного за другим. Англичане назовут это «фоккеровским бичом».'},
      {t:'Продавать синхронизатор и другим заводам',fx:{cash:1500,b:{airFight:[1.03,24]}},res:'Синхронизатор ставят на «Альбатросы» и «Хальберштадты». Фоккер получает отчисления — а соперники получают его изобретение.'},
      {t:'Держать в секрете и строить только у себя',fx:{cash:800,b:{airMil:[1.1,24]}},res:'Армия заказывает «Фоккеры» сотнями. Секрет живёт, пока один «Фоккер», заблудившись, не сядет на английском аэродроме.'}]},
  {id:'fo3',t:'Триплан и «Семёрка»',y:1918,when:'t:1918.1',
   sc:[{img:'Fokker Dr.I',say:'1917 год. «Альбатросы» и «Сопвичи» обогнали фоккеровские монопланы. Новый главный конструктор Фоккера, бывший сварщик Рейнгольд Платц, строит трёхкрылый истребитель — вёрткий, как оса.'},
       {img:'Manfred von Richthofen',say:'На красном триплане летает Манфред фон Рихтгофен — «Красный барон». Он сбил больше шестидесяти машин — больше всех на фронте.'},
       {img:'Fokker D.VII',say:'Январь 1918 года, Адлерсхоф, конкурс истребителей. Ночью Фоккер сам переделывает свой биплан: удлиняет фюзеляж. Утром Рихтгофен облетает машину и говорит: «Вот она». D.VII побеждает.'},
       {who:'Офицер инспекции',line:'Ваш завод столько не сделает, господин Фоккер. D.VII будет строить и «Альбатрос» — по вашим чертежам. Вам — отчисления с каждой машины.'}],
   q:'Как строить D.VII?',
   o:[{t:'Отдать чертежи «Альбатросу» за отчисления',fx:{cash:2000,b:{airMil:[1.06,24]}},res:'«Альбатрос» построит D.VII больше, чем сам Фоккер. Отчисления идут, а на фронте D.VII пугает союзников.'},
      {t:'Строить у себя — в три смены',fx:{cash:1200,b:{airFight:[1.08,24]}},res:'Шверин работает днём и ночью. Лётчики говорят: из плохого лётчика D.VII делает хорошего.'},
      {t:'Самому — на фронт, к лётчикам',fx:{afame:4,b:{airQ:[1.03,24]}},res:'Фоккер ездит по фронтовым аэродромам, слушает лётчиков и меняет машину прямо в поле. Ему верят больше, чем инспекторам.'}]},
  {id:'fo4',t:'Шесть эшелонов',y:1919,when:'t:1919.75',
   v:[{if:s=>!!(s.air&&s.air.abroad),
     sc:[{img:'Armistice of 11 November 1918',say:'Перемирие. Отдельным пунктом союзники требуют сдать все истребители D.VII — так их боятся. Версальский договор запрещает Германии авиацию совсем.'},
         {say:'Фоккер подкупает пограничников и железнодорожников. Шесть эшелонов — двести двадцать аэропланов, четыреста моторов, станки — уходят в Голландию. Завод начинает заново под Амстердамом.'},
         {who:'Механик',line:'Минхер Фоккер, мы дома. Только кому теперь нужны истребители?'}],
     q:'Что строить в Голландии?',
     o:[{t:'Пассажирские монопланы',fx:{cash:-1000,b:{airMulti:[1.08,36],airDev:[0.92,24]}},res:'Толстое деревянное крыло без растяжек, закрытая кабина на несколько пассажиров. Голландская авиалиния КЛМ берёт первые «Фоккеры».'},
        {t:'Продавать истребители всем, кто платит',fx:{cash:1500,afame:-2},res:'D.VII покупают голландская армия, Швейцария — все, у кого есть деньги. Деньги нужны сейчас, а угрызения совести подождут.'},
        {t:'Открыть фирму в Америке',fx:{cash:800,afame:2,b:{airPriv:[1.06,36]}},res:'Фоккер открывает в Америке своё отделение. Скоро на его машинах будут летать полярники и авиалинии.'}]}],
   sc:[{img:'Armistice of 11 November 1918',say:'Перемирие. Отдельным пунктом союзники требуют сдать все истребители D.VII — так их боятся. Версальский договор запрещает Германии строить аэропланы.'},
       {say:'Союзная комиссия опечатывает ангары и режет моторы. Фоккер мог бы вывезти завод в Голландию — шесть эшелонов, подкупленные пограничники, — но пока цеха стоят под замком.'},
       {who:'Механик',line:'Минхер Фоккер, комиссия приходит каждую неделю. Если вывозить — то сейчас.'}],
   q:'Что делать?',
   o:[{t:'Вывезти завод в Голландию',fx:{cash:-1200,abroad:1,b:{airMulti:[1.05,36]}},res:'Ночью эшелоны уходят к границе. В Голландии завод начинает заново — с пассажирских монопланов.'},
      {t:'Ждать, пока снимут запрет',fx:{cash:600,b:{airDev:[1.1,24]}},res:'Цеха делают мебель и лодки. Конструкторы чертят в стол — до лучших времён.'},
      {t:'Продать склады и уехать в Америку',fx:{cash:2500,afame:-2},res:'Склады уходят за бесценок. Фоккер едет за океан — начинать с громким именем, но почти без завода.'}]},
  {id:'fo5',t:'Трёхмоторный «Фоккер»',y:1926,when:'t:1926.5',
   sc:[{img:'Fokker F.VII',say:'1925 год. Генри Форд устраивает перелёт на надёжность по всей Америке. Фоккер ставит на пассажирский F.VII три мотора «Райт Вихрь» — и проходит маршрут без единого штрафа. Трёхмоторный «Фоккер» становится самым желанным лайнером мира.'},
       {img:'Richard E. Byrd',say:'В мае 1926 года на трёхмоторном «Фоккере» «Жозефина Форд» Ричард Бёрд летит к Северному полюсу. А в 1928 году «Южный Крест» Кингсфорда Смита перелетит Тихий океан.'},
       {who:'Директор авиалинии',line:'Один мотор отказал — долетим на двух. Пассажиры это понимают. Дайте нам двадцать таких машин.'}],
   q:'Как расти?',
   o:[{t:'Завод в Америке',fx:{cash:-1200,b:{airMulti:[1.08,36],airPriv:[1.05,36]}},res:'Американская фирма Фоккера строит лайнеры для новых авиалиний. Скоро её долю купит «Дженерал Моторс».'},
      {t:'Лицензии — пусть строят по всему миру',fx:{cash:1500,b:{airQ:[0.99,24]}},res:'F.VII строят по лицензии в Англии, Бельгии, Польше и Чехословакии. Отчисления текут в Амстердам.'},
      {t:'Рекордные перелёты',fx:{afame:5,b:{airFame:[1.2,36]}},res:'Полюс, океаны, континенты — «Фоккеры» везде первые. Имя Фоккера знает весь мир.'}]},
  {id:'fo6',t:'Деревянное крыло',y:1929,when:'t:1929.75',
   sc:[{img:'Wall Street crash of 1929',say:'Октябрь 1929 года. Паника на нью-йоркской бирже. Весной Фоккер успел продать долю американской фирмы «Дженерал Моторс» — вовремя.'},
       {say:'Но деревянное крыло его лайнеров стареет: в нём заводятся гниль и трещины, которых не видно снаружи. Конкуренты строят из металла.'},
       {who:'Инженер',line:'Минхер Фоккер, металл дороже и тяжелее. Но дерево в сыром ангаре живёт недолго. Однажды крыло не выдержит.'}],
   q:'С чем войти в тридцатые?',
   o:[{t:'Переходить на металл',fx:{cash:-1500,b:{airQ:[1.05,36],airTech:[0.85,24]}},res:'Металлическое крыло — дорого и долго. Но в 1931 году, когда в Канзасе развалится деревянное крыло «Фоккера» с футбольным тренером Кнутом Рокни на борту, ваши машины будут уже металлическими.'},
      {t:'Беречь деньги',fx:{cash:2500,afame:-2,b:{airDev:[1.1,24]}},res:'Сейф полон. Фоккер покупает яхту и летает для удовольствия.'},
      {t:'Продать американское дело целиком',fx:{cash:4000,afame:-3},res:'«Дженерал Моторс» забирает американскую фирму целиком. Фоккер возвращается в Голландию — к своим первым мастерам.'}]}
];

SAGA.junkers=[
  {id:'ju1',t:'Профессор и железо',y:1915,when:'start',
   sc:[{img:'Hugo Junkers',say:'Хуго Юнкерс — профессор термодинамики из Ахена и фабрикант из Дессау: его газовые колонки греют воду во многих немецких квартирах. Ему пятьдесят шесть лет.'},
       {say:'Ещё в 1910 году он запатентовал толстое крыло, внутри которого помещается всё — моторы, баки, даже пассажиры. Аэроплан будущего, говорит Юнкерс, — моноплан без растяжек и целиком из металла.'},
       {who:'Генерал инспекции',line:'Железный аэроплан, профессор? Он не взлетит. А если взлетит — не поднимется выше колокольни.'}],
   q:'Чем платить за опыты?',
   o:[{t:'Своими деньгами — завод колонок оплатит',fx:{cash:-800,b:{airDev:[0.9,24]}},res:'Юнкерс платит из своего кармана и ни у кого не спрашивает разрешения. Работа идёт быстро — пока есть деньги.'},
      {t:'Просить у армии',fx:{cash:600,b:{airMil:[1.06,36],airDev:[1.1,24]}},res:'Инспекция даёт деньги и требует отчётов. Каждое изменение — через три подписи.'},
      {t:'Молодые инженеры из Ахена',fx:{cash:-300,b:{airQ:[1.04,36]}},res:'Профессор зовёт своих студентов. Они считают крыло по формулам, а не на глаз, — так в авиации ещё никто не работал.'}]},
  {id:'ju2',t:'Жестяной осёл',y:1916,when:'t:1916.0',
   sc:[{img:'Junkers J 1',say:'Двенадцатое декабря 1915 года, Дёбериц. Моноплан Юнкерса J 1 — из листовой стали, без единой растяжки — отрывается от земли. Он быстрее многих бипланов, но тяжёл и неохотно набирает высоту.'},
       {say:'Лётчики прозовут его «Жестяным ослом». Армия заказов не даёт. Но Юнкерс уже знает, что делать: нужен лёгкий сплав — дюраль, из которого граф Цеппелин строит каркасы своих дирижаблей.'},
       {who:'Инженер Отто Мадер',line:'Если гофрировать тонкий лист дюраля, он станет жёстким, как доска. Обшивка сама будет держать крыло.'}],
   q:'Из чего строить дальше?',
   o:[{t:'Дюраль — лёгкий сплав цеппелинов',fx:{cash:-800,b:{airQ:[1.05,36],airTech:[0.85,24]}},res:'Гофрированный дюраль станет визитной карточкой Юнкерса на двадцать лет. Его аэропланы узнают по «стиральной доске» на крыльях.'},
      {t:'Броня — штурмовик для пехоты',fx:{b:{airMil:[1.1,36]}},res:'Бронированный биплан Юнкерса летает над окопами на бреющем полёте: пули отскакивают от стальной ванны вокруг мотора и экипажа.'},
      {t:'Оставить сталь — дешевле',fx:{b:{airCost:[0.92,24],airQ:[0.97,24]}},res:'Сталь дешева и привычна. Машины выходят тяжёлыми, но армия ценит, что их не берёт сырость.'}]},
  {id:'ju3',t:'Брак по расчёту',y:1917,when:'t:1917.85',
   sc:[{img:'Anthony Fokker',say:'Октябрь 1917 года. Инспекция недовольна: профессор строит слишком медленно. По её требованию Юнкерс объединяется с Антони Фоккером — в общую фирму «Юнкерс-Фоккер».'},
       {say:'Фоккер — молодой, быстрый, весёлый, ему всё равно, из чего строить, лишь бы летало. Юнкерс — педант, который пересчитывает каждую заклёпку. Они не выносят друг друга.'},
       {who:'Антони Фоккер',line:'Профессор, война кончится раньше, чем вы досчитаете своё крыло. Дайте мне чертежи — я построю его за месяц.'}],
   q:'Как ужиться с Фоккером?',
   o:[{t:'Пустить Фоккера в цеха',fx:{b:{airDev:[0.85,24],airQ:[0.97,24]}},res:'Фоккер торопит мастеров, и машины выходят быстрее. Профессор ворчит: заклёпки кривые.'},
      {t:'Деньги армии — а чертежи свои',fx:{cash:1000,b:{airQ:[1.04,24]}},res:'Деньги армии — в кассе, чертежи Юнкерса — в его сейфе. Фоккер злится, но в цехах распоряжается профессор.'},
      {t:'Разорвать союз при первом случае',fx:{afame:-1,b:{airDev:[1.05,12],airTech:[0.9,24]}},res:'После войны «Юнкерс-Фоккер» распадётся. Профессор вздохнёт свободно и вернётся к своим металлическим монопланам.'}]},
  {id:'ju4',t:'F 13',y:1919,when:'t:1919.6',
   v:[{if:s=>!!(s.air&&s.air.abroad),
     o:[{t:'В Америку — почтовой службе',fx:{cash:1200,b:{airPriv:[1.05,24]}},res:'F 13 летают с почтой над Америкой под чужим именем. Деньги идут, хотя американские механики не любят непривычный металл.'},
        {t:'Своя авиалиния «Юнкерс»',fx:{cash:-1200,afame:3,b:{airMulti:[1.08,36]}},res:'Авиалиния Юнкерса связывает города Германии и Европы. Пассажиры привыкают к гофрированным крыльям.'},
        {t:'Расширить заводы за границей',fx:{cash:-800,b:{airQ:[1.03,36],airMulti:[1.04,36]}},res:'Под Москвой, в Филях, Юнкерс получает пустующий завод «Руссо-Балта», в Швеции — завод под Мальмё. Версаль там не достанет.'}]}],
   sc:[{img:'Junkers F 13',say:'Двадцать пятое июня 1919 года. Взлетает Юнкерс F 13 — первый в мире цельнометаллический пассажирский аэроплан: закрытая тёплая кабина на четверых, кожаные кресла, окна. В сентябре он поднимет восемь человек на шесть с половиной километров — мировой рекорд.'},
       {say:'Но Германия проиграла войну. Союзная комиссия опечатывает заводы и режет моторы, а F 13 то и дело объявляют военным аэропланом.'},
       {who:'Американский агент',line:'Профессор, нашей почтовой службе нужны металлические аэропланы. Мы купим ваши F 13 — под американским именем.'}],
   q:'Куда продавать F 13?',
   o:[{t:'В Америку — почтовой службе',fx:{cash:1200,b:{airPriv:[1.05,24]}},res:'F 13 летают с почтой над Америкой под чужим именем. Деньги идут, хотя американские механики не любят непривычный металл.'},
      {t:'Своя авиалиния «Юнкерс»',fx:{cash:-1200,afame:3,b:{airMulti:[1.08,36]}},res:'Авиалиния Юнкерса связывает города Германии и Европы. Пассажиры привыкают к гофрированным крыльям.'},
      {t:'Строить за границей — в Швеции и в России',fx:{cash:-1000,abroad:1},res:'Под Москвой, в Филях, Юнкерс получает пустующий завод «Руссо-Балта», в Швеции — завод под Мальмё. Версаль там не достанет.'}]},
  {id:'ju5',t:'Люфтганза',y:1926,when:'t:1926.1',
   sc:[{img:'Junkers G 24',say:'1926 год. Трёхмоторный G 24 возит пассажиров по всей Европе. Но завод в Филях принёс одни убытки: Красная армия заказывала мало и платила неохотно.'},
       {say:'Правительство предлагает спасение: авиалиния Юнкерса и её соперница «Аэро Ллойд» сольются в одну — «Дойче Люфт Ганза». А долги профессора казна возьмёт на себя — не даром.'},
       {who:'Чиновник министерства',line:'Профессор, у вас нет выбора. Или вы отдаёте авиалинию, или банки закрывают ваши заводы.'}],
   q:'Отдать авиалинию?',
   o:[{t:'Отдать — и спасти завод',fx:{cash:2000,afame:-2},res:'Профессор подписывает. Его «Юнкерсы» летают под флагом «Люфтганзы», а заводы в Дессау снова работают.'},
      {t:'Бороться в суде',fx:{cash:-800,afame:2,b:{airDev:[1.08,24]}},res:'Суды тянутся годами. Юнкерс отстаивает своё, но деньги уходят на адвокатов.'},
      {t:'Продавать машины всему миру',fx:{cash:800,b:{airPriv:[1.08,36],airMulti:[1.04,36]}},res:'«Юнкерсы» летают в Южной Америке, Персии, Китае и над льдами Канады. Профессор считает не рейсы, а страны.'}]},
  {id:'ju6',t:'«Бремен»',y:1928,when:'t:1928.35',
   sc:[{img:'Bremen (aircraft)',say:'Апрель 1928 года. Металлический «Юнкерс» W 33 «Бремен» вылетает из Ирландии на запад — против ветра, через Атлантику. Его ведут немцы Кёль и фон Хюнефельд и ирландец Фицморис.'},
       {say:'Тридцать шесть часов в тумане и метели — и вынужденная посадка на крохотном острове Грили у берегов Канады. Первый перелёт через Атлантику с востока на запад! В Нью-Йорке лётчиков встречают парадом.'},
       {who:'Хуго Юнкерс',line:'Металл выдержал океан. Теперь — крыло, внутри которого летят пассажиры.'}],
   q:'Что дальше?',
   o:[{t:'Гигант G 38 — летающее крыло',fx:{cash:-1500,b:{airMulti:[1.1,36],airTech:[0.85,24]}},res:'В толстом крыле G 38 — места для пассажиров с окнами в передней кромке. Он полетит осенью 1929 года.'},
      {t:'Рекордные перелёты — реклама металла',fx:{afame:5,b:{airFame:[1.2,36]}},res:'«Юнкерсы» летают над океанами и континентами. Каждый рекорд — реклама гофрированного дюраля.'},
      {t:'Грузовые машины для всего мира',fx:{cash:1000,b:{airPriv:[1.06,36]}},res:'«Юнкерсы» возят грузы на золотые прииски Новой Гвинеи и в тайгу Канады. Скромно — зато каждый день.'}]},
  {id:'ju7',t:'Профессор и время',y:1929,when:'t:1929.84',
   sc:[{img:'Junkers G 38',say:'Ноябрь 1929 года. Взлетает G 38 — самый большой сухопутный аэроплан в мире. Хуго Юнкерсу семьдесят лет.'},
       {img:'Wall Street crash of 1929',say:'А месяцем раньше рухнула нью-йоркская биржа. Германия живёт на американских займах — и займы кончаются.'},
       {who:'Хуго Юнкерс',line:'Я строил металлические аэропланы, когда все смеялись. Пусть смеются и теперь — G 38 полетел.'}],
   q:'С чем войти в тридцатые?',
   o:[{t:'Новый трёхмоторный транспортник',fx:{cash:-1500,b:{airMulti:[1.08,36],airDev:[0.92,24]}},res:'Чертёжники рисуют простой трёхмоторный моноплан из гофрированного дюраля. Через несколько лет его назовут «Тётушка Ю» — Ю-52.'},
      {t:'Беречь деньги',fx:{cash:2500,afame:-2,b:{airDev:[1.1,24]}},res:'Сейф полон, профессор недоволен. Банкиры довольны.'},
      {t:'Продать долю государству',fx:{cash:4000,afame:-3},res:'Деньги нужны сейчас. Но в 1933 году новая власть отберёт у Юнкерса его заводы целиком.'}]}
];

SAGA.sopwith=[
  {id:'so1',t:'Каток в Кингстоне',y:1912,when:'start',
   sc:[{img:'Thomas Sopwith',say:'Томас Сопвич — богатый наследник, яхтсмен и автогонщик. В 1910 году он сам научился летать в Бруклендсе, а через месяц выиграл приз барона де Форе: пролетел из Англии на континент дальше всех.'},
       {img:'Brooklands',say:'В июне 1912 года он снимает пустой каток для роликовых коньков в Кингстоне-на-Темзе. С ним — механик Фред Сигрист и молодой австралиец Гарри Хокер, приехавший в Англию с несколькими фунтами в кармане.'},
       {who:'Гарри Хокер',line:'Мистер Сопвич, дайте мне полетать на том, что мы строим. Я знаю каждую заклёпку в этой машине.'}],
   q:'С чего начать?',
   o:[{t:'Хокер — лётчик-испытатель',fx:{afame:3,b:{airFame:[1.1,36]}},res:'Хокер летает на всём, что строят в Кингстоне, и ставит британские рекорды высоты и продолжительности полёта.'},
      {t:'Летающая лодка для флота',fx:{cash:-400,b:{airMil:[1.08,36]}},res:'Летающая лодка Сопвича садится и на воду, и на землю. Адмиралтейство заказывает первые машины.'},
      {t:'Сигрист наводит порядок в мастерской',fx:{b:{airQ:[1.04,36],airCost:[0.95,24]}},res:'Сигрист расписывает каждую операцию и считает каждый фунт. Кингстон работает как часы.'}]},
  {id:'so2',t:'«Таблоид»',y:1914,when:'t:1914.33',
   v:[{if:s=>airSagaWon(s,'schneider-1914'),
     sc:[{img:'Sopwith Tabloid',say:'Апрель 1914 года, Монако. Кубок Шнейдера для гидроаэропланов. Маленький «Таблоид» Сопвича на поплавках проходит двести восемьдесят километров почти со скоростью сто сорок километров в час — вдвое быстрее прошлогоднего победителя.'},
         {say:'После финиша лётчик проходит ещё два круга — и ставит мировой рекорд скорости для гидроаэропланов. Британия впервые берёт кубок.'},
         {who:'Томас Сопвич',line:'Маленький, быстрый, послушный. Армия захочет такой же — только на колёсах.'}]}],
   sc:[{img:'Sopwith Tabloid',say:'Ноябрь 1913 года. Хокер привозит в Фарнборо маленький биплан «Таблоид»: сто сорок пять километров в час и подъём быстрее всего, что летает в Англии. Военные не верят приборам и просят повторить.'},
       {say:'Весной 1914 года «Таблоид» на поплавках выходит на Кубок Шнейдера в Монако. Это уже не громоздкая коробка: так будут выглядеть истребители.'},
       {who:'Томас Сопвич',line:'Маленький, быстрый, послушный. Армия захочет такой же — только на колёсах.'}],
   q:'Кому строить «Таблоид»?',
   o:[{t:'Армии — быстрый разведчик',fx:{b:{airMil:[1.1,36]}},res:'Первые «Таблоиды» уходят в Королевский лётный корпус. Разведчик, который обгоняет всех, — генералы впервые понимают, зачем нужна скорость.'},
      {t:'Флоту — на поплавках',fx:{cash:-300,b:{airMil:[1.08,36],airQ:[1.02,24]}},res:'Морская авиация берёт «Таблоиды». В октябре 1914 года один из них сожжёт цеппелин прямо в эллинге под Дюссельдорфом.'},
      {t:'Гоночные — для призов',fx:{afame:3,b:{airFame:[1.15,24]}},res:'«Таблоид» берёт приз за призом. Слава Сопвича растёт быстрее завода.'}]},
  {id:'so3',t:'«Пап» и «Кэмел»',y:1916,when:['airWar','t:1916.5'],
   sc:[{img:'Sopwith Pup',say:'1916 год. «Полуторастоечный» Сопвича — первый британский аэроплан с пулемётом, стреляющим через винт. За ним — лёгкий «Пап», щенок: лётчики его обожают.'},
       {img:'Sopwith Camel',say:'Потом — «Кэмел», верблюд: горб над пулемётами. Ротативный мотор так резко тянет его вбок, что новички разбиваются на первом же вираже. Но в руках мастера он сбивает больше немцев, чем любой другой истребитель союзников.'},
       {who:'Командир эскадрильи',line:'Мне нужны «Кэмелы» — и лётчики, которые не убьются на них в первый же день.'}],
   q:'Как строить для войны?',
   o:[{t:'Лицензии — пусть строят все',fx:{cash:2500,b:{airMil:[1.08,24]}},res:'«Кэмелы» строят десяток заводов по всей Англии. Их сделают больше пяти тысяч.'},
      {t:'Учебный «Кэмел» с двойным управлением',fx:{cash:-400,afame:2,b:{airQ:[1.04,36]}},res:'Курсанты учатся летать на «Кэмеле» вдвоём с инструктором. Катастроф в школах становится меньше.'},
      {t:'Корабельный «Кэмел» для флота',fx:{cash:-300,b:{airMil:[1.06,36],airFight:[1.04,36]}},res:'«Кэмелы» взлетают с площадок на башнях линкоров и с первых авианосцев. В июле 1918 года они разбомбят цеппелиновую базу в Тондерне.'}]},
  {id:'so4',t:'Атлантика',y:1919,when:'t:1919.45',
   v:[{if:s=>airSagaWon(s,'atlantic-1919'),
     sc:[{img:'Sopwith Atlantic',say:'Май 1919 года. «Дейли Мейл» снова обещает десять тысяч фунтов — за перелёт через Атлантику без посадки. На Ньюфаундленде собираются соперники.'},
         {say:'Машина из Кингстона долетает до Ирландии! В Лондоне лётчиков встречают тысячи людей, король жмёт им руки. Приз — у Сопвича.'},
         {who:'Томас Сопвич',line:'Война кончилась, а мы всё ещё умеем делать невозможное.'}]}],
   sc:[{img:'Sopwith Atlantic',say:'Май 1919 года. «Дейли Мейл» снова обещает десять тысяч фунтов — за перелёт через Атлантику без посадки. Гарри Хокер и штурман Маккензи-Грив вылетают с Ньюфаундленда на «Сопвиче Атлантик».'},
       {say:'Через четырнадцать часов перегревается мотор. Хокер сажает машину на воду рядом с датским пароходом «Мэри» — радио на нём нет. Неделю Англия считает лётчиков погибшими, король посылает вдове соболезнование. А потом пароход подходит к Шотландии — оба живы!'},
       {say:'Через месяц Алкок и Браун на «Виккерсе Вими» перелетают океан и берут приз. «Дейли Мейл» вручает Хокеру утешительные пять тысяч фунтов.'}],
   q:'Что дальше?',
   o:[{t:'Новая машина — для новых рекордов',fx:{cash:-800,afame:3,b:{airFame:[1.1,24]}},res:'Кингстон строит новый дальний аэроплан. Океан уже перелетели, но рекордов хватит на всех.'},
      {t:'Мотоциклы и кузова — переждать',fx:{cash:1200,b:{airDev:[1.1,24]}},res:'Сопвич выпускает мотоциклы ABC и кузова для автомобилей. Заводу нужна работа, пока небо пустует.'},
      {t:'Пассажирские аэропланы',fx:{cash:-800,b:{airMulti:[1.05,36]}},res:'Сопвич переделывает военные машины для пассажиров. Покупателей мало: на складах тысячи дешёвых армейских аэропланов.'}]},
  {id:'so5',t:'Налог на сверхприбыль',y:1920,when:'t:1920.7',
   sc:[{img:'Harry Hawker',say:'1920 год. Казна требует с Сопвича налог на военную сверхприбыль — столько, что у фирмы не хватит денег. Заказов нет, мотоциклы не спасают.'},
       {say:'Сопвич решает: лучше закрыть фирму самому, чем ждать банкротства. Он расплатится с каждым кредитором до последнего пенни.'},
       {who:'Гарри Хокер',line:'Томми, давай начнём заново. Маленькой фирмой, с нашими людьми. Можно под моим именем — я же теперь знаменит.'}],
   q:'Как спасти дело?',
   o:[{t:'Закрыть фирму и начать заново — «Хокер»',fx:{cash:-800,b:{airDev:[0.9,36],airQ:[1.03,36]}},res:'В ноябре 1920 года Сопвич, Хокер, Сигрист и Эйр открывают «Эйч Джи Хокер Инжиниринг». Через несколько лет главным конструктором станет Сидни Кэмм — и «Хокеры» будут лучшими истребителями Британии.'},
      {t:'Заплатить налог сполна',fx:{cash:-2500,afame:2},res:'Касса пуста, но имя чисто. Кингстон работает вполсилы.'},
      {t:'Судиться с казной',fx:{cash:-500,afame:-2,b:{airDev:[1.08,24]}},res:'Адвокаты дороги, суд тянется. Конструкторы ждут, чем всё кончится.'}]},
  {id:'so6',t:'«Хокеры»',y:1929,when:'t:1929.75',
   sc:[{img:'Hawker Woodcock',say:'Двенадцатого июля 1921 года Гарри Хокер разбился на аэродроме Хендон, готовясь к гонке. Его имя осталось на воротах фирмы.'},
       {say:'1929 год. Лёгкий бомбардировщик «Харт» Сидни Кэмма летает быстрее истребителей Королевских ВВС. Министерство просит такой же истребитель.'},
       {img:'Wall Street crash of 1929',say:'А в октябре рушится нью-йоркская биржа. Министерство считает каждый фунт.'}],
   q:'С чем войти в тридцатые?',
   o:[{t:'Истребитель «Фьюри» — быстрее всех',fx:{cash:-1500,b:{airFight:[1.1,36],airDev:[0.92,24]}},res:'Через два года «Фьюри» станет первым истребителем Королевских ВВС, который летает быстрее трёхсот двадцати километров в час.'},
      {t:'Беречь деньги',fx:{cash:2500,afame:-2,b:{airDev:[1.1,24]}},res:'Сейф полон. Сопвич строит яхту — и через несколько лет поплывёт за Кубком Америки.'},
      {t:'Скупать других',fx:{cash:-1200,b:{airMil:[1.06,36]}},res:'Так и будет: «Хокер» купит «Глостер», «Армстронг-Уитворт» и «Авро». А сам Сопвич проживёт сто один год.'}]}
];

SAGA.dehav=[
  {id:'dh1',t:'Аэроплан на дедушкины деньги',y:1910,when:'start',
   sc:[{img:'Geoffrey de Havilland',say:'Джеффри де Хэвилленд — сын сельского священника. Он строил моторы для лондонских автобусов, а на тысячу фунтов, которые дал ему дед, построил аэроплан — и мотор к нему.'},
       {say:'В декабре 1909 года первый аэроплан разбился на первом же взлёте. Де Хэвилленд выбрался из-под обломков, снял уцелевший мотор и начал второй — вместе с другом, механиком Фрэнком Херлом.'},
       {who:'Фрэнк Херл',line:'Мотор цел, Джеффри. Крылья сделаем полегче — и на этот раз сначала подлёты, а уж потом полёт.'}],
   q:'Как жить дальше?',
   o:[{t:'Продать аэроплан армии — и остаться конструктором',fx:{cash:600,b:{airMil:[1.1,36]}},res:'В конце 1910 года армия покупает второй аэроплан де Хэвилленда за четыреста фунтов. Конструктора зовут в Фарнборо — на королевскую авиафабрику.'},
      {t:'Строить дальше на свои',fx:{afame:2,b:{airQ:[1.03,24]}},res:'Де Хэвилленд и Херл работают в сарае под Ньюбери. Медленно — но каждая деталь проверена.'},
      {t:'Учить летать за деньги',fx:{cash:400,b:{airPriv:[1.06,24]}},res:'Ученики платят немного, зато регулярно. Аэроплан ломается чаще, чем хотелось бы.'}]},
  {id:'dh2',t:'Устойчивый разведчик',y:1912,when:'t:1912.7',
   sc:[{img:'Royal Aircraft Factory B.E.2',say:'Август 1912 года, Солсберийская равнина. Военный конкурс аэропланов. Биплан де Хэвилленда B.E.2 выступает вне конкурса — и оказывается лучше победителя.'},
       {say:'Двенадцатого августа де Хэвилленд поднимает его с пассажиром на три тысячи двести метров — британский рекорд высоты. Армия заказывает B.E.2 — устойчивый разведчик, который летит почти сам.'},
       {who:'Майор Сайкс',line:'Наблюдатель должен смотреть вниз и рисовать карту, а не держаться за борт. Ваш аэроплан это позволяет.'}],
   q:'Что дальше?',
   o:[{t:'Устойчивые разведчики для армии',fx:{b:{airMil:[1.1,36],airQ:[1.03,24]}},res:'B.E.2 строят десятки заводов. Устойчивость — его сила; в 1915 году, против «Фоккеров», она станет его слабостью.'},
      {t:'Быстрые одноместные — на будущее',fx:{cash:-500,b:{airFight:[1.06,36]}},res:'Де Хэвилленд рисует маленький быстрый разведчик. Генералы не понимают, зачем он, — пока не начнётся война.'},
      {t:'Рекорды высоты',fx:{afame:3,b:{airFame:[1.1,24]}},res:'Де Хэвилленд поднимается всё выше. Газеты пишут о нём как о лучшем лётчике-конструкторе Англии.'}]},
  {id:'dh3',t:'DH.2 и DH.4',y:1915,when:['airWar','t:1915.5'],
   sc:[{img:'Airco DH.2',say:'1915 год. У британцев нет синхронизатора, а немецкие «Фоккеры» стреляют через винт. Де Хэвилленд ставит мотор сзади, а пулемёт — впереди: истребитель-толкач DH.2.'},
       {img:'Airco DH.4',say:'А в 1916 году он строит DH.4 — лучший дневной бомбардировщик войны: быстрый и высотный, он уходит от истребителей. Американцы построят по его чертежам почти пять тысяч машин с мотором «Либерти».'},
       {who:'Холт Томас',line:'Джеффри, у моей фирмы «Эйрко» есть завод, деньги и заказы. У вас — голова. Давайте работать вместе.'}],
   q:'Как работать в войну?',
   o:[{t:'Истребитель-толкач DH.2',fx:{cash:-500,b:{airFight:[1.08,24]}},res:'DH.2 приходит на фронт в начале 1916 года и помогает покончить с «фоккеровским бичом».'},
      {t:'Дневной бомбардировщик DH.4',fx:{cash:1200,b:{airMil:[1.1,36]}},res:'DH.4 строят тысячами в Англии и Америке. Его экипажи говорят: если нас и догонят, то только на пикировании.'},
      {t:'Лицензия в Америку',fx:{cash:2000,b:{airQ:[0.99,24]}},res:'Американцы платят за чертежи. Их DH.4 с мотором «Либерти» будет возить почту ещё восемь лет после войны.'}]},
  {id:'dh4',t:'Лондон — Париж',y:1919,when:'t:1919.7',
   sc:[{img:'Airco DH.16',say:'Двадцать пятое августа 1919 года. С аэродрома Хаунслоу под Лондоном в Париж уходит первый в мире ежедневный международный рейс. Аэроплан — переделанный бомбардировщик де Хэвилленда: четыре пассажира в закрытой кабине за спиной у лётчика.'},
       {say:'Билет стоит двадцать гиней — больше месячного заработка рабочего. Летают дельцы, дипломаты и газетчики. Через год с небольшим у линии кончатся деньги.'},
       {who:'Холт Томас',line:'Пассажиров мало, субсидий нет, а французы летают на государственные деньги. Мы долго не продержимся.'}],
   q:'Что делать?',
   o:[{t:'Своя авиалиния — держаться до конца',fx:{cash:-1000,afame:3,b:{airMulti:[1.05,36]}},res:'Линия держится на упрямстве. Пассажиров всё больше, но денег — всё меньше.'},
      {t:'Продавать пассажирские машины другим',fx:{cash:800,b:{airMulti:[1.04,24]}},res:'Голландская КЛМ начинает свои рейсы на аэроплане де Хэвилленда. Так начинается самая старая из авиалиний мира.'},
      {t:'Вернуться к спортивным машинам',fx:{b:{airPriv:[1.08,36]}},res:'Де Хэвилленд снова думает о лёгком аэроплане для любителей. До «Мотылька» ещё пять лет.'}]},
  {id:'dh5',t:'Стэг-Лейн',y:1920,when:'t:1920.8',
   sc:[{img:'Stag Lane Aerodrome',say:'1920 год. Фирму «Эйрко» покупает оружейный концерн BSA — и тут же закрывает авиацию. Де Хэвилленд остаётся без завода.'},
       {say:'В сентябре 1920 года он открывает свою фирму на маленьком аэродроме Стэг-Лейн под Лондоном. Деньги — от бывшего хозяина Холта Томаса и от своих же сотрудников. Ангары — бывшие армейские бараки.'},
       {who:'Алан Батлер',line:'Я хочу купить у вас аэроплан для себя. А заодно вложить в вашу фирму немного денег. Если позволите.'}],
   q:'На чём строить фирму?',
   o:[{t:'Взять деньги Батлера',fx:{cash:1200,b:{airPriv:[1.05,24]}},res:'Алан Батлер станет председателем правления. Его деньги помогут фирме пережить самые трудные годы.'},
      {t:'Чинить и переделывать армейские машины',fx:{cash:800,b:{airQ:[1.02,24]}},res:'Стэг-Лейн берёт любую работу: ремонт, переделку, аэрофотосъёмку. Не слава — зато жалованье каждую пятницу.'},
      {t:'Только свои машины — даже без денег',fx:{cash:-500,afame:2,b:{airDev:[0.92,24]}},res:'Де Хэвилленд рискует, но каждая новая машина — его. Скоро это окупится.'}]},
  {id:'dh6',t:'«Мотылёк»',y:1925,when:'t:1925.3',
   sc:[{img:'de Havilland DH.60 Moth',say:'Двадцать второе февраля 1925 года. Де Хэвилленд сам поднимает в воздух маленький двухместный биплан «Мотылёк». Мотор дешёвый, крылья складываются, держать машину можно в гараже.'},
       {say:'Министерство авиации дарит пяти аэроклубам по два «Мотылька». Через несколько лет летать на «Мотыльке» умеют врачи, фермеры, студенты и молодые дамы — по всей империи.'},
       {who:'Фрэнк Халфорд',line:'Чужой мотор дорог и капризен. Я сделаю вам свой — четыре цилиндра в ряд, лёгкий и надёжный. Назовём его «Цыган».'}],
   q:'Как растить «Мотылька»?',
   o:[{t:'Свой мотор «Цыган»',fx:{cash:-1000,b:{airEng:[0.85,36]}},res:'Мотор Халфорда делает «Мотылька» дешевле и надёжнее. «Цыганский Мотылёк» станет самым популярным лёгким самолётом мира.'},
      {t:'Аэроклубы по всей империи',fx:{b:{airPriv:[1.15,36]}},res:'«Мотыльки» летают в Канаде, Австралии, Индии и Южной Африке. Аэроклуб без «Мотылька» — не аэроклуб.'},
      {t:'Дальние перелёты на «Мотыльке»',fx:{afame:4,b:{airFame:[1.15,36]}},res:'Лётчики летят на «Мотыльках» в Кейптаун и в Индию. Каждый перелёт — реклама лучше любой газеты.'}]},
  {id:'dh7',t:'Эми и «Джейсон»',y:1929,when:'t:1929.75',
   sc:[{img:'Wall Street crash of 1929',say:'Октябрь 1929 года. Паника на нью-йоркской бирже. А в Стэг-Лейн строят новый моноплан с закрытой кабиной — «Пусс Мотылёк».'},
       {img:'Amy Johnson',say:'Молодая секретарша из Гулля Эми Джонсон учится летать в Лондонском аэроклубе — на «Мотыльке». Через полгода она полетит на нём в Австралию одна.'},
       {who:'Эми Джонсон',line:'Мистер де Хэвилленд, если ваша машина долетит до Австралии, то долетит куда угодно. Я это докажу.'}],
   q:'С чем войти в тридцатые?',
   o:[{t:'Новые «Мотыльки» — для всех',fx:{cash:-1200,b:{airPriv:[1.12,36],airDev:[0.92,24]}},res:'«Пусс Мотылёк», «Тигровый Мотылёк» — семья растёт. На «Тигровом» будут учиться лётчики всей Британии.'},
      {t:'Беречь деньги',fx:{cash:2500,afame:-2,b:{airDev:[1.1,24]}},res:'Сейф полон. Конструкторы чертят в стол.'},
      {t:'Пассажирские машины для империи',fx:{cash:-1000,b:{airMulti:[1.08,36]}},res:'Многомоторные «де Хэвилленды» полетят на линиях Африки и Австралии. Империи нужны крылья.'}]}
];

SAGA.caproni=[
  {id:'ca1',t:'Пустошь Мальпенса',y:1910,when:'start',
   sc:[{img:'Giovanni Battista Caproni',say:'Джанни Капрони родился в Трентино, которое тогда принадлежало Австрии. Он учился в Мюнхене и Льеже, а в 1910 году построил свой первый аэроплан в сарае у фермы Мальпенса — на пустоши под Миланом.'},
       {say:'Двадцать седьмого мая его Ca.1 поднимается в воздух — и разбивается на посадке. Капрони не лётчик: летают его пилоты, а он чертит и ищет деньги.'},
       {who:'Механик',line:'Синьор Капрони, денег хватит на один аэроплан. Если разобьём и его — возвращаемся в Трентино.'}],
   q:'С чего начать?',
   o:[{t:'Лётная школа на пустоши',fx:{cash:400,b:{airPriv:[1.08,24]}},res:'Школа Капрони в Виццоле учит лётчиков, а заодно испытывает новые машины. Ученики платят — и ломают.'},
      {t:'Мечта о большом аэроплане',fx:{cash:-500,b:{airMulti:[1.08,36]}},res:'Капрони рисует аэроплан с тремя моторами — для пассажиров или для бомб. Над ним смеются. Пока.'},
      {t:'Продавать маленькие монопланы',fx:{cash:700,b:{airQ:[0.98,24]}},res:'Монопланы Капрони покупают спортсмены и армия. Денег немного, но дело живёт.'}]},
  {id:'ca2',t:'Три мотора',y:1914,when:'t:1914.85',
   sc:[{img:'Caproni Ca.3',say:'Октябрь 1914 года. В Европе война, Италия пока нейтральна. Над Виццолой поднимается большой биплан Капрони: два мотора тянут, третий толкает. Он поднимает сотни килограммов бомб — или десяток пассажиров.'},
       {say:'Капрони и его друг, офицер Джулио Дуэ, мечтают о воздушном флоте, который решит исход войны.'},
       {who:'Джулио Дуэ',line:'Армия будет воевать в горах годами. А бомбардировщик перелетит Альпы за час.'}],
   q:'Кому предложить бомбардировщик?',
   o:[{t:'Итальянской армии — ещё до войны',fx:{b:{airMil:[1.12,36]}},res:'Армия заказывает первые машины. Когда в мае 1915 года Италия вступит в войну, у неё будут свои бомбардировщики.'},
      {t:'Франции и России',fx:{cash:1200,b:{airQ:[0.99,24]}},res:'«Капрони» строят по лицензии во Франции. Деньги приходят, пока Италия думает.'},
      {t:'Пассажирский вариант — на будущее',fx:{cash:-400,b:{airMulti:[1.06,36]}},res:'В фюзеляже — скамьи для пассажиров. После войны пригодится.'}]},
  {id:'ca3',t:'Через Альпы',y:1915,when:'airWar',
   sc:[{img:'Caproni Ca.3',say:'Май 1915 года. Италия вступает в войну. Бомбардировщики Капрони летят через Альпы на австрийские заводы, станции и порты.'},
       {img:'Gabriele D\'Annunzio',say:'Поэт Габриэле д’Аннунцио летает наблюдателем на «Капрони» и пишет о налётах стихи. В 1917 году он ведёт ночной налёт на австрийскую базу флота в Каттаро.'},
       {who:'Генерал Кадорна',line:'Мне нужно больше бомбардировщиков, чем вы можете построить. Стройте больше.'}],
   q:'Как работать в войну?',
   o:[{t:'Строить сотнями',fx:{cash:2500,b:{airMil:[1.1,24]}},res:'Заводы Капрони растут по всей Ломбардии. Бомбардировщики уходят на фронт эскадрильями.'},
      {t:'Огромный триплан для ночных налётов',fx:{cash:-800,b:{airMulti:[1.1,36]}},res:'Трёхкрылый Ca.4 с тремя моторами поднимает полторы тонны бомб. Медленный, как дирижабль, но ночью его не видно.'},
      {t:'Лицензии — Франции и Америке',fx:{cash:1500,b:{airQ:[0.99,24]}},res:'Бомбардировщики Капрони строят во Франции, а американцы покупают лицензию для своего воздушного флота.'}]},
  {id:'ca4',t:'«Трансаэро»',y:1921,when:'t:1921.25',
   sc:[{img:'Caproni Ca.60',say:'После войны Капрони строит мечту — летающую лодку на сто пассажиров: девять крыльев тремя этажами, восемь моторов. Её называют «Трансаэро» — она должна летать через Атлантику.'},
       {say:'Четвёртого марта 1921 года, на втором полёте над озером Маджоре, «Трансаэро» поднимается на двадцать метров — и рушится в воду. Лётчик выжил. От лодки остались обломки.'},
       {who:'Механик',line:'Синьор Капрони, мы можем её восстановить. Но денег хватит только на это — или на всё остальное.'}],
   q:'Что делать?',
   o:[{t:'Восстанавливать «Трансаэро»',fx:{cash:-1500,afame:2,b:{airMulti:[1.05,36]}},res:'Мастера собирают гиганта снова. Он больше не полетит — но опыт пригодится для больших машин.'},
      {t:'Бросить гиганта — делать то, что покупают',fx:{cash:500,b:{airDev:[0.9,24]}},res:'Капрони возвращается к бомбардировщикам и учебным машинам. Армия снова заказывает.'},
      {t:'Пассажирские машины поменьше',fx:{cash:-600,b:{airMulti:[1.08,36]}},res:'Небольшие пассажирские «Капрони» летают между городами Италии. Скромнее мечты — зато летают.'}]},
  {id:'ca5',t:'Музей и заводы',y:1929,when:'t:1929.75',
   sc:[{img:'Wall Street crash of 1929',say:'Октябрь 1929 года. Паника на бирже. А Капрони — уже не мастерская на пустоши, а группа заводов по всей Италии.'},
       {say:'Капрони собирает старые аэропланы — в музей. Ему кажется, что история авиации пишется на его глазах и её нужно сберечь.'},
       {who:'Тимина Капрони',line:'Джанни, у нас уже больше старых аэропланов, чем места в ангаре. Это музей или завод?'}],
   q:'С чем войти в тридцатые?',
   o:[{t:'Новые бомбардировщики и транспортники',fx:{cash:-1500,b:{airMulti:[1.08,36],airMil:[1.05,36]}},res:'Армия и колонии ждут больших машин. Заводы Капрони работают в полную силу.'},
      {t:'Беречь деньги',fx:{cash:2500,afame:-2,b:{airDev:[1.1,24]}},res:'Сейф полон, музей растёт.'},
      {t:'Скупать заводы — свои моторы',fx:{cash:-1200,b:{airEng:[0.88,36]}},res:'Капрони покупает моторный завод «Изотта Фраскини». Своя группа — свои моторы.'}]}
];

/* ---------- Сикорский: Киев, «Витязь», «Муромец», революция — и Америка или «красный директор» ---------- */
const SIK_US=s=>!s.soviet&&(!s.emig||s.emig.to==='us');   // уехал в Америку — или по истории (старое сохранение)
const SIK_EMIG={
  sc:[{img:'x:ru-petrograd-1917',say:'Позади Петроград, Мурманск, пароходы и пересадки. Русские лётчики и инженеры рассеяны по всему свету: кто водит такси в Париже, кто чертит для чужих заводов.'},
      {who:'Лётчик-эмигрант',line:'Игорь Иванович, нас здесь десяток — лётчики и механики эскадры. Возьмите нас. Работать будем за двоих.'},
      {say:'Новая страна, новый рынок — и послевоенный кризис. Начинать приходится почти с нуля.'}],
  q:'С чего начать заново?',
  o:[{t:'Нанять своих — лётчиков и механиков эскадры',fx:{cash:-500,b:{airDev:[0.88,36],airQ:[1.03,24]}},res:'Конструкторское бюро говорит по-русски. Чертежи, вывезенные из России, оживают на новом месте.'},
     {t:'Летающие лодки для линий над морем',fx:{cash:-800,b:{airMulti:[1.08,36]}},res:'Амфибия садится на воду и на землю. Авиалинии над морем ждут именно такую машину.'},
     {t:'Продать вывезенные чертежи',fx:{cash:1200,afame:-2},res:'Местные фирмы платят за русские чертежи. Деньги нужны сейчас, а идеи будут новые.'}]};
const SIK_END_O=[{t:'Большие летающие лодки — «Клипперы»',fx:{cash:-1500,b:{airMulti:[1.1,36]}},res:'Огромные летающие лодки Сикорского полетят через Карибское море, а потом и через Тихий океан.'},
  {t:'Вернуться к вертолёту',fx:{cash:-800,afame:2,b:{airTech:[0.8,36]}},res:'Сикорский достаёт киевские чертежи 1909 года. Через десять лет его вертолёт наконец оторвётся от земли.'},
  {t:'Беречь деньги',fx:{cash:2500,afame:-2,b:{airDev:[1.1,24]}},res:'Сейф полон, конструкторы скучают.'}];
SAGA.sikorsky=[
  {id:'si1',t:'Сарай во дворе',y:1910,when:'start',
   sc:[{img:'Igor Sikorsky',say:'Киев. Игорь Сикорский — сын профессора-психиатра и студент политехнического. В 1909 году он съездил в Париж, купил мотор «Анзани» и построил вертолёт. Вертолёт не взлетел.'},
       {say:'Тогда Сикорский взялся за аэроплан. С-1 только подпрыгивал. Летом 1910 года С-2 оторвался от земли — на несколько секунд.'},
       {who:'Сестра Ольга',line:'Игорь, бери мою часть. Отец ворчит, но я верю: полетишь.'}],
   q:'Вертолёт или аэроплан?',
   o:[{t:'Отложить вертолёт — строить аэропланы',fx:{b:{airDev:[0.92,24],airQ:[1.02,24]}},res:'Вертолёт ждёт лучших моторов и знаний. Сикорский вернётся к нему через тридцать лет — в Америке.'},
      {t:'Упорствовать с вертолётом',fx:{cash:-500,afame:1,b:{airTech:[0.8,36]}},res:'Второй вертолёт поднимет сам себя, но не лётчика. Зато Сикорский научится считать винты лучше всех в России.'},
      {t:'Снова в Париж — учиться у других',fx:{cash:-300,b:{airQ:[1.04,24]}},res:'Сикорский снова в Париже: смотрит, расспрашивает, покупает чертежи. Домой он возвращается с новыми идеями.'}]},
  {id:'si2',t:'Московский конкурс',y:1912,when:'t:1912.75',
   v:[{if:s=>airSagaWon(s,'mosmil-1912'),
     sc:[{img:'Igor Sikorsky',say:'Сентябрь 1912 года. Московский конкурс военных аэропланов. Трёхместный С-6Б Сикорского обходит иностранные машины — первый приз и заказ военного ведомства.'},
         {say:'Председатель правления «Руссо-Балта» Михаил Шидловский предлагает молодому конструктору возглавить авиационный отдел завода в Петербурге.'},
         {who:'Михаил Шидловский',line:'Игорь Иванович, у «Руссо-Балта» есть цеха, мастера и деньги. У вас — голова. Стройте у нас, что хотите.'}]}],
   sc:[{img:'Igor Sikorsky',say:'Сентябрь 1912 года. Московский конкурс военных аэропланов: иностранные машины, русские машины, генералы с биноклями. Киевского студента здесь уже знают: его С-6 поставил рекорд скорости с двумя пассажирами.'},
       {say:'Председатель правления «Руссо-Балта» Михаил Шидловский предлагает молодому конструктору возглавить авиационный отдел завода в Петербурге.'},
       {who:'Михаил Шидловский',line:'Игорь Иванович, у «Руссо-Балта» есть цеха, мастера и деньги. У вас — голова. Стройте у нас, что хотите.'}],
   q:'Принять предложение «Руссо-Балта»?',
   o:[{t:'Да — завод и деньги Шидловского',fx:{cash:1500,b:{airQ:[1.03,36],airMulti:[1.05,36]}},res:'Сикорский переезжает в Петербург. В цехах «Руссо-Балта» он начинает строить то, о чём мечтал: большой аэроплан.',
       after:{mo:4,from:'Михаил Шидловский',text:'Игорь Иванович, цех для вас освобождён, стапели ставят, мастера из вагонного отдела переведены. Правление ждёт чертежи большого аэроплана к Рождеству — и очень просит не говорить газетам, сколько у него моторов. Шидловский.'}},
      {t:'Остаться независимым в Киеве',fx:{afame:2,b:{airDev:[0.95,24]}},res:'Своя мастерская, свои решения. Денег мало, зато никто не мешает.'},
      {t:'Взять заказ армии на разведчики',fx:{cash:800,b:{airMil:[1.1,36]}},res:'Армия заказывает лёгкие машины. Скучно — но мастерская растёт.'}]},
  {id:'si3',t:'«Русский витязь»',y:1913,when:'t:1913.6',
   v:[{if:s=>sagaPicked(s,'si2',1),
     sc:[{img:'Sikorsky Russky Vityaz',say:'Год назад Сикорский отказал Шидловскому и остался в Киеве. Но Шидловский упрям: он снова приехал — с чертёжным столом в поезде — и уговорил строить большой аэроплан в Петербурге, на средства «Руссо-Балта», с именем Сикорского на борту.'},
         {say:'Май 1913 года. Над Комендантским аэродромом поднимается невиданная машина: четыре мотора, закрытая кабина с окнами, диваном и умывальником, балкон на носу. «Русский витязь» — первый в мире четырёхмоторный аэроплан.'},
         {who:'Механик',line:'Игорь Иванович, мотор отказал — а мы летим дальше на трёх. Значит, большой аэроплан не страшен!'},
         {say:'А в сентябре на стоящий у ангара «Витязь» падает мотор с пролетавшего над аэродромом аэроплана. Крыло разбито. Чинить его Сикорский не станет — он уже строит новый, ещё больше.'}]}],
   sc:[{img:'Sikorsky Russky Vityaz',say:'Май 1913 года, Петербург. Над Комендантским аэродромом поднимается невиданная машина: четыре мотора, закрытая кабина с окнами, диваном и умывальником, балкон на носу. «Русский витязь» — первый в мире четырёхмоторный аэроплан.'},
       {say:'Европейские газеты не верили, что такая махина полетит. Летом его осматривает император Николай Второй: поднимается на балкон и долго расспрашивает конструктора.'},
       {who:'Механик',line:'Игорь Иванович, мотор отказал — а мы летим дальше на трёх. Значит, большой аэроплан не страшен!'},
       {say:'А в сентябре на стоящий у ангара «Витязь» падает мотор с пролетавшего над аэродромом аэроплана. Крыло разбито. Чинить его Сикорский не станет — он уже строит новый, ещё больше.'}],
   q:'Что строить после «Витязя»?',
   o:[{t:'Ещё больше — «Илья Муромец»',fx:{cash:-1000,b:{airMulti:[1.12,36]}},res:'Новый гигант Сикорского назовут именем богатыря — «Илья Муромец». Он поднимет шестнадцать человек.'},
      {t:'Лёгкие разведчики для армии',fx:{b:{airMil:[1.1,36]}},res:'Армия заказывает лёгкие машины Сикорского. Большой аэроплан подождёт.'},
      {t:'Продать идею за границу',fx:{cash:1200,afame:-1},res:'Иностранцы платят за чертежи. Деньги нужны, но первенство России остаётся на бумаге.'}]},
  {id:'si4',t:'«Илья Муромец»',y:1914,when:'t:1914.55',
   v:[{if:s=>airSagaWon(s,'kiev-1914'),
     sc:[{img:'Sikorsky Ilya Muromets',say:'Июнь 1914 года. «Илья Муромец» летит из Петербурга в Киев с остановкой в Орше. В полёте загорается мотор: механики выходят прямо на крыло и сбивают пламя куртками.'},
         {say:'Дальше — облака и туман. Сикорский ведёт машину вслепую, по приборам. Обратный путь — за тринадцать часов. Россия празднует.'},
         {who:'Механик',line:'Игорь Иванович, мы горели в воздухе, летели в облаках — и долетели. Теперь этот аэроплан ничего не испугает.'}]}],
   sc:[{img:'Sikorsky Ilya Muromets',say:'Зимой «Илья Муромец» поднял шестнадцать человек и аэродромную собаку по кличке Шкалик. Сикорский мечтает долететь на нём из Петербурга в Киев.'},
       {say:'Через месяц начнётся война. Большой аэроплан нужен армии — разведчиком и бомбардировщиком.'},
       {who:'Механик',line:'Игорь Иванович, мотор откажет — долетим на трёх. Этот аэроплан ничего не испугает.'}],
   q:'Что дальше?',
   o:[{t:'Пассажирские «Муромцы»',fx:{cash:-800,b:{airMulti:[1.08,36]}},res:'Сикорский рисует воздушный лайнер для линии Петербург — Москва. Но война не даст ему полететь с пассажирами.'},
      {t:'Армии — бомбардировщик',fx:{b:{airMil:[1.12,36]}},res:'Военное ведомство заказывает «Муромцы». Скоро из них соберут целую эскадру.'},
      {t:'Флоту — «Муромец» на поплавках',fx:{cash:-300,b:{airMil:[1.06,36]}},res:'Гидроаэроплан «Илья Муромец» поднимается с воды. Флот присматривается.'}]},
  {id:'si5',t:'Эскадра воздушных кораблей',y:1915,when:['airWar','t:1915.1'],
   sc:[{img:'Sikorsky Ilya Muromets',say:'Декабрь 1914 года. Из «Муромцев» собирают Эскадру воздушных кораблей во главе с Шидловским. Первый боевой вылет — в феврале 1915-го.'},
       {say:'Корабль несёт полтонны бомб и пулемёты во все стороны. За всю войну немецкие истребители собьют лишь один «Муромец» — и он заберёт с собой троих.'},
       {who:'Генерал Шидловский',line:'Игорь Иванович, моторов не хватает. Союзники присылают мало, свои делает только «Руссо-Балт». Что будем делать?'}],
   q:'Как воевать?',
   o:[{t:'Строить «Муромцы» для эскадры',fx:{cash:1500,b:{airMulti:[1.1,36]}},res:'«Муромцы» уходят на фронт один за другим. Эскадра бьёт по станциям и складам.'},
      {t:'Истребитель для охраны',fx:{cash:-500,b:{airFight:[1.08,36]}},res:'Маленький С-16 с синхронным пулемётом охраняет аэродромы эскадры.'},
      {t:'Свои моторы — без иностранцев',fx:{cash:-800,b:{airEng:[0.88,36]}},res:'«Руссо-Балт» строит свои моторы. Они тяжелее французских, но их не нужно ждать из-за моря.'}]},
  {id:'si6',t:'Через Мурманск',y:1918,when:'t:1918.6',
   v:[{if:s=>!!s.soviet,t:'Красный директор',
     sc:[{img:'x:ru-bolshevik-armour-1917',say:'Декрет о национализации: завод — собственность республики. Сикорский остался. Теперь он «красный директор», а над ним — главк и комиссары.'},
         {say:'Гражданская война. «Муромцы» без моторов стоят в ангарах. Лётчики эскадры — кто у красных, кто у белых, кто уже за границей.'},
         {who:'Комиссар',line:'Товарищ директор, Красному воздушному флоту нужны аэропланы. Любые. Что можете дать к весне?'}],
     q:'Как работать при новой власти?',
     o:[{t:'Чинить старые машины для Красной армии',fx:{cash:900,b:{airMil:[1.06,36]}},res:'Цеха восстанавливают разбитые «Ньюпоры» и «Фарманы». Работа неблагодарная, но завод живёт.'},
        {t:'Учить молодых конструкторов',fx:{cash:-500,b:{airDev:[0.9,36],airQ:[1.03,36]}},res:'Студенты приходят с рабфаков. Через десять лет они будут строить самолёты для всей страны.'},
        {t:'Беречь чертежи «Муромца»',fx:{afame:2,b:{airMulti:[1.06,36]}},res:'Чертежи большого аэроплана лежат в сейфе. Когда-нибудь стране снова понадобятся тяжёлые машины.'}]}],
   sc:[{img:'x:ru-petrograd-1917',say:'Петроград, зима 1918 года. Заводы стоят, «Руссо-Балт» национализируют, за инженерами-«буржуями» приходят по ночам. Сикорскому шепчут: уезжай.'},
       {say:'Через Мурманск, на британском пароходе, с несколькими сотнями фунтов в кармане, он уезжает во Францию. Там ему заказывают бомбардировщик — но в ноябре кончается война, и заказ отменяют.'},
       {who:'Игорь Сикорский',line:'Начинать придётся с нуля. Но большим аэропланам нужна большая страна — найдём и её.'}],
   q:'Куда дальше?',
   o:[{t:'Начинать с нуля — на новом месте',fx:{cash:-300,afame:1,b:{airDev:[0.95,24]}},res:'Сикорский преподаёт математику эмигрантам и читает лекции об авиации. Денег почти нет, но мечта цела.'},
      {t:'Работать на чужие фирмы',fx:{cash:800,b:{airQ:[1.02,24]}},res:'Русский конструктор чертит для чужих заводов. Платят исправно, но имени на машинах нет.'},
      {t:'Собрать русских инженеров-эмигрантов',fx:{cash:-500,b:{airDev:[0.88,36],airQ:[1.03,24]}},res:'Русские инженеры и лётчики, офицеры бывшей эскадры, — лучшая команда, о какой можно мечтать.'}]},
  {id:'si7',t:'Ферма на Лонг-Айленде',y:1923,when:'t:1923.4',
   v:[{if:s=>!!s.soviet,t:'«Добролёт»',
     sc:[{img:'x:ru-chervonets-1922',say:'Нэп. В 1923 году создаётся общество «Добролёт»: пассажирские и почтовые линии над Россией. Акции покупают граждане, а плакаты зовут: «Граждане, стройте воздушный флот!»'},
         {say:'А в Филях, на бывшем заводе «Руссо-Балта», немцы Юнкерса строят металлические самолёты по секретному договору. Молодой инженер Туполев пробует свой — из кольчугалюминия.'},
         {who:'Председатель треста',line:'Товарищ директор, страна должна летать на своих самолётах. Ни немецких, ни английских.'}],
     q:'Что строить для страны?',
     o:[{t:'Пассажирские машины для «Добролёта»',fx:{cash:-600,b:{airMulti:[1.06,36]}},res:'Небольшие пассажирские самолёты летают в Нижний Новгород, Харьков и Тифлис. Люди учатся летать за свой червонец.'},
        {t:'Металлические самолёты — как у Туполева',fx:{cash:-800,b:{airTech:[0.85,36],airQ:[1.03,36]}},res:'Кольчугалюминий, гофрированная обшивка, новые станки. Металл приходит в русскую авиацию.'},
        {t:'Учебные машины для аэроклубов',fx:{cash:700,b:{airPriv:[1.08,36]}},res:'Аэроклубы открываются по всей стране. Тысячи комсомольцев учатся летать.'}]},
     {if:s=>!SIK_US(s),t:'На чужбине',...SIK_EMIG}],
   sc:[{img:'Sergei Rachmaninoff',say:'Март 1923 года. Русские эмигранты основывают на Лонг-Айленде фирму Сикорского — в курятнике на ферме лётчика Виктора Утгофа. Деньги вкладывают такие же беглецы. Композитор Сергей Рахманинов вносит пять тысяч долларов и соглашается стать вице-президентом.'},
       {img:'Sikorsky S-29-A',say:'Самолёт С-29-А — «А» значит «Америка» — строят из того, что находят на свалках. В мае 1924 года на первом полёте он едва дотягивает до поля для гольфа.'},
       {who:'Сергей Рахманинов',line:'Игорь Иванович, я ничего не понимаю в аэропланах. Но я понимаю в упрямстве. Летите.'}],
   q:'Как выжить в Америке?',
   o:[{t:'Чинить и строить С-29-А заново',fx:{cash:-600,afame:2,b:{airMulti:[1.06,36]}},res:'Второй С-29-А летает. Его покупает лётчик-гастролёр и катает публику над Нью-Йорком. Говорят, однажды он перевёз даже рояль.'},
      {t:'Летающие лодки — для линий над морем',fx:{cash:-800,b:{airMulti:[1.08,36],airPriv:[1.04,24]}},res:'Сикорский рисует амфибию — она садится и на воду, и на землю. Молодая авиалиния «Пан Американ» скоро о ней узнает.'},
      {t:'Самолёт для перелёта через океан',fx:{cash:-1000,afame:3,b:{airFame:[1.15,36]}},res:'Французский ас Рене Фонк заказывает трёхмоторный С-35 для приза Ортейга. В сентябре 1926 года перегруженная машина разобьётся на взлёте. Сикорский будет помнить об этом всю жизнь.'}]},
  {id:'si8',t:'Большие лодки',y:1929,when:'t:1929.75',
   v:[{if:s=>!!s.soviet,t:'Великий перелом',
     sc:[{img:'x:ru-plan-poster-1930',say:'1929 год. Первая пятилетка: стране нужны самолёты — сотни, тысячи. Частников больше нет, есть тресты и план.'},
         {say:'Летом металлический пассажирский АНТ-9 «Крылья Советов» облетел Европу: Берлин, Париж, Рим, Лондон, Варшава. Россия снова строит большие самолёты — как когда-то «Муромцы».'},
         {who:'Нарком',line:'Догнать и перегнать! План — закон, товарищ директор.'}],
     q:'Как выполнять пятилетку?',
     o:[{t:'Встречный план — вдвое больше',fx:{afame:2,b:{airMil:[1.08,36],airQ:[0.95,24]}},res:'Цеха работают в три смены, о браке молчат. Завод в газетах — среди передовых.'},
        {t:'Большие самолёты — как «Муромец»',fx:{cash:-1000,b:{airMulti:[1.1,36]}},res:'Чертежи большого аэроплана достают из сейфа. Стране снова нужны воздушные корабли.'},
        {t:'Надёжно, без спешки',fx:{afame:-2,b:{airQ:[1.06,36]}},res:'Самолёты выходят надёжными, но план не выполнен. Директору ставят на вид.'}]},
     {if:s=>!SIK_US(s),t:'Чёрный четверг на чужбине',
     sc:[{img:'Wall Street crash of 1929',say:'Октябрь 1929 года. Паника на нью-йоркской бирже, по всему миру дрожат банки. Беглецы из России обжились на новом месте, завод снова на ногах.'},
         {who:'Лётчик-эмигрант',line:'Помните, как мы уходили через Мурманск? А теперь у нас свой ангар и свои машины.'},
         {say:'А дома, в Советской России, — пятилетка и новые заводы. Туда уже не вернуться.'}],
     q:'С чем войти в тридцатые?',o:SIK_END_O}],
   sc:[{img:'Sikorsky S-38',say:'1928 год. Амфибия С-38 Сикорского летает для «Пан Американ» над Карибским морем: садится на воду у островов, где нет аэродромов. Заказы идут десятками.'},
       {say:'Летом 1929 года фирма входит в концерн «Юнайтед Эркрафт» и переезжает в Стратфорд, штат Коннектикут, — на берег реки, где можно спускать на воду летающие лодки.'},
       {img:'Wall Street crash of 1929',say:'А в октябре рушится нью-йоркская биржа. Сикорский смотрит на реку и думает о больших лодках — через океан.'}],
   q:'С чем войти в тридцатые?',
   o:SIK_END_O}
];
